import {serve} from '@hono/node-server';import {serveStatic} from '@hono/node-server/serve-static';import {Hono} from 'hono';import {z} from 'zod';import {calculate,type RequestInput} from './logic.js';
declare const process:{env:Record<string,string|undefined>};const maxBodyBytes=16_384;const schema=z.object({bid_key:z.string(),solar_arrays:z.number().int(),wind_turbines:z.number().int(),storage_banks:z.number().int(),interconnects:z.number().int(),emergency_mode:z.boolean(),duplicate_bid:z.boolean()}).strict();
const response=(value:unknown,status=200,headers:Record<string,string>={})=>{if(Object.keys(headers).some(name=>['content-length','content-type','connection','transfer-encoding','x-content-type-options'].includes(name.toLowerCase())))return new Response(JSON.stringify({error:'invalid_response_headers',detail:'server-owned response header'}),{status:500,headers:{'content-type':'application/json'}});return new Response(JSON.stringify(value),{status,headers:{'content-type':'application/json',...headers}})};const error=(code:string,status:number,detail:string)=>response({error:code,detail},status);const zero=(v:RequestInput,state:string)=>({bid_key:v.bid_key,generation_units:0,battery_buffer_units:0,grid_required_units:0,grid_capacity_units:0,delivered_units:0,shortfall_units:0,dispatch_windows:0,bid_score:0,bid_state:state});const decide=(v:RequestInput,headers:Headers)=>{if((headers.get('x-grid-key')??'')!=="grid-045")return response(zero(v,'authorization_required'),401,{"www-authenticate":"GridKey"});if([v.solar_arrays,v.wind_turbines,v.storage_banks,v.interconnects].some(item=>item<0))return response(zero(v,'invalid'),422,{'x-validation':'nonnegative'});if(v.interconnects===0&&v.solar_arrays*9+v.wind_turbines*13>0)return response(zero(v,'invalid'),422,{'x-validation':'interconnects'});if(v.duplicate_bid)return response(zero(v,'duplicate'),409,{'x-conflict':'duplicate_bid'});return response(calculate(v),200,{});};
const app=new Hono();app.get('/status/microgrid-bid-ready',()=>response({service:'Microgrid Bid',ready:true}));app.post('/api/v9/microgrid-bids',async context=>{const media=(context.req.header('content-type')??'').split(';',1)[0]!.trim().toLowerCase();if(media!=='application/json'&&!media.endsWith('+json'))return error('json_content_type_required',415,'expected application/json');const declared=context.req.header('content-length');if(declared&&(!/^\d+$/.test(declared)||Number(declared)>maxBodyBytes))return error('body_too_large',413,'request body exceeds 16384 bytes');const raw=await context.req.arrayBuffer();if(raw.byteLength>maxBodyBytes)return error('body_too_large',413,'request body exceeds 16384 bytes');try{const parsed=schema.safeParse(JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(raw)));if(!parsed.success)return error('invalid_json',400,parsed.error.message);return decide(parsed.data,context.req.raw.headers)}catch(caught){return error('invalid_json',400,String(caught))}});app.all('/api/*',context=>error('not_found',404,`no API route ${context.req.path}`));app.get('/parley.js',serveStatic({path:process.env.FULLSTACK_045_BROWSER??'./dist/logic.js'}));app.get('/*',serveStatic({root:'./public'}));serve({fetch:app.fetch,hostname:'127.0.0.1',port:Number(process.env.PARLEY_WEB_PORT)});
